using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 public static class MapDetailBaker {
  static readonly Color[] crops={Hex(0x9F907A),Hex(0xA99982),Hex(0xB6A68B),Hex(0xB9A577),Hex(0x9B876E)};
  static Color Hex(int color){return StaffMapStyle.Hex(color);}
  public struct Statistics{public int fields,buildings,villages,diagonalEdges,roadAlignedEdges,inkEdges,rejectedPlots,clippedFieldPixels;public float smallestField,largestField;public int[] palette;public List<Vector2> villageCentres;}
  sealed class Painter {
   public MapDetailRegions data;public StaffMapCanvas canvas;public Statistics stats;
   readonly RecoveryPoint[] cities;readonly ResourceSite[] sites;
   readonly Dictionary<long,bool> safe=new Dictionary<long,bool>();
   bool[] fieldPixels;
   readonly List<List<Vector2>> occupiedFields=new List<List<Vector2>>();
   static bool Contains(List<Vector2> polygon,Vector2 p){float sign=0;for(int i=0;i<polygon.Count;i++){var a=polygon[i];var d=polygon[(i+1)%polygon.Count]-a;float cross=d.x*(p.y-a.y)-d.y*(p.x-a.x);if(Mathf.Abs(cross)<.00001f)continue;if(sign==0)sign=Mathf.Sign(cross);else if(sign*cross<0)return false;}return true;}
   static float Distance(List<Vector2> polygon,Vector2 point){if(Contains(polygon,point))return 0;float best=float.PositiveInfinity;for(int i=0;i<polygon.Count;i++){var a=polygon[i];var d=polygon[(i+1)%polygon.Count]-a;best=Mathf.Min(best,Vector2.Distance(point,a+d*Mathf.Clamp01(Vector2.Dot(point-a,d)/Mathf.Max(.00001f,d.sqrMagnitude))));}return best;}
   static List<Vector2> Inset(List<Vector2> polygon,float amount){var centre=Centre(polygon);var result=polygon;for(int i=0;i<polygon.Count&&result.Count>=3;i++){var a=polygon[i];var d=polygon[(i+1)%polygon.Count]-a;var normal=new Vector2(-d.y,d.x).normalized;if(Vector2.Dot(centre-a,normal)<0)normal=-normal;result=Clip(result,normal,Vector2.Dot(a,normal)+amount,true);}return result;}
   bool ClearPlot(List<Vector2> polygon,List<Vector2> villages){
    if(polygon.Count<3||Area(polygon)<.18f||villages.Any(p=>Distance(polygon,p)<1.5f))return false;
    // Validate the entire holding before drawing. Keep complete straight boundaries instead of cutting with a terrain raster.
    foreach(var previous in occupiedFields){bool separated=false;foreach(var shape in new[]{previous,polygon})for(int i=0;i<shape.Count;i++){var d=shape[(i+1)%shape.Count]-shape[i];var axis=new Vector2(-d.y,d.x).normalized;if(previous.Max(p=>Vector2.Dot(p,axis))+.04f<polygon.Min(p=>Vector2.Dot(p,axis))||polygon.Max(p=>Vector2.Dot(p,axis))+.04f<previous.Min(p=>Vector2.Dot(p,axis))){separated=true;break;}}if(!separated)return false;}
    for(int i=0;i<polygon.Count;i++){var a=polygon[i];var b=polygon[(i+1)%polygon.Count];int steps=Mathf.Max(1,Mathf.CeilToInt(Vector2.Distance(a,b)/.05f));for(int n=0;n<=steps;n++){var p=Vector2.Lerp(a,b,n/(float)steps);for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++)if(!Safe(p+new Vector2(dx,dy)*.20f))return false;}}
    float x0=polygon.Min(p=>p.x),x1=polygon.Max(p=>p.x),y0=polygon.Min(p=>p.y),y1=polygon.Max(p=>p.y);for(float y=y0;y<=y1;y+=.06f)for(float x=x0;x<=x1;x+=.06f){var p=new Vector2(x,y);if(Contains(polygon,p)&&!Safe(p))return false;}return true;
   }
   public Painter(MapDetailRegions d,int width){data=d;d.Resolve();var b=d.terrain.definition.bounds;canvas=new StaffMapCanvas(width,Mathf.RoundToInt(width*b.height/b.width),b);stats=new Statistics{palette=new int[5],villageCentres=new List<Vector2>()};cities=UnityEngine.Object.FindObjectsOfType<RecoveryPoint>().Where(p=>p.gameObject.scene==d.gameObject.scene).ToArray();sites=UnityEngine.Object.FindObjectsOfType<ResourceSite>().Where(p=>p.gameObject.scene==d.gameObject.scene).ToArray();}
   bool Safe(Vector2 p){int x=Mathf.FloorToInt(p.x/.06f),y=Mathf.FloorToInt(p.y/.06f);long key=((long)x<<32)^(uint)y;bool value;if(safe.TryGetValue(key,out value))return value;var world=data.terrain.transform.TransformPoint(new Vector3(p.x,p.y,0));var k=data.terrain.TerrainAt(new RoadPoint(world.x,world.y));value=k==TerrainKind.Ground||k==TerrainKind.Grass;if(value&&data.terrain.waterMap!=null&&data.terrain.waterMap.IsRawWater(new RoadPoint(world.x,world.y)))value=false;
    if(value)foreach(var edge in data.roads.definition.connections){Vector2 a=data.terrain.transform.InverseTransformPoint(data.roads.transform.TransformPoint(data.roads.definition.nodes[edge.a])),b=data.terrain.transform.InverseTransformPoint(data.roads.transform.TransformPoint(data.roads.definition.nodes[edge.b]));var delta=b-a;float t=delta.sqrMagnitude==0?0:Mathf.Clamp01(Vector2.Dot(p-a,delta)/delta.sqrMagnitude);if(Vector2.Distance(p,a+delta*t)<data.roads.definition.roadWidth*.5f+.09f){value=false;break;}}
    if(value)foreach(var city in cities)if(Vector2.Distance(world,city.transform.position)<.7f){value=false;break;}if(value)foreach(var site in sites)if(site.Area.Contains(world)||Vector2.Distance(world,site.transform.position)<1){value=false;break;}safe[key]=value;return value;
   }
   bool Fits(Rect area,Vector2 p,float margin){return area.Contains(p-Vector2.one*margin)&&area.Contains(p+Vector2.one*margin)&&Safe(p)&&Safe(p+Vector2.right*margin)&&Safe(p-Vector2.right*margin)&&Safe(p+Vector2.up*margin)&&Safe(p-Vector2.up*margin);}
   static float Next(System.Random r,float lo,float hi){return Mathf.Lerp(lo,hi,(float)r.NextDouble());}
   static Vector2 Centre(List<Vector2> p){Vector2 sum=Vector2.zero;foreach(var v in p)sum+=v;return sum/p.Count;}
   static float Area(List<Vector2> p){float sum=0;for(int i=0;i<p.Count;i++){var a=p[i];var b=p[(i+1)%p.Count];sum+=a.x*b.y-b.x*a.y;}return Mathf.Abs(sum)*.5f;}
   static List<Vector2> Clip(List<Vector2> polygon,Vector2 normal,float offset,bool positive){var result=new List<Vector2>();for(int i=0;i<polygon.Count;i++){var a=polygon[i];var b=polygon[(i+1)%polygon.Count];float da=Vector2.Dot(a,normal)-offset,db=Vector2.Dot(b,normal)-offset;bool ina=positive?da>=0:da<=0,inb=positive?db>=0:db<=0;if(ina)result.Add(a);if(ina!=inb)result.Add(Vector2.Lerp(a,b,da/(da-db)));}return result;}
   Vector2 RoadDirection(Vector2 point){float best=float.PositiveInfinity;Vector2 direction=Vector2.right;
    foreach(var edge in data.roads.definition.connections){Vector2 a=data.terrain.transform.InverseTransformPoint(data.roads.transform.TransformPoint(data.roads.definition.nodes[edge.a])),b=data.terrain.transform.InverseTransformPoint(data.roads.transform.TransformPoint(data.roads.definition.nodes[edge.b]));var d=b-a;if(d.sqrMagnitude<.0001f)continue;var foot=a+d*Mathf.Clamp01(Vector2.Dot(point-a,d)/d.sqrMagnitude);float distance=(point-foot).sqrMagnitude;if(distance<best){best=distance;direction=d.normalized;}}return direction;}
   void Partition(List<Vector2> polygon,float target,System.Random random,List<List<Vector2>> plots,int depth=0){if(polygon.Count<3)return;if(Area(polygon)<target*1.7f||depth>=13){plots.Add(polygon);return;}
    // Work in the nearest road's frame. Small deviations keep holdings irregular without random wedges.
    var direction=RoadDirection(Centre(polygon));var across=new Vector2(-direction.y,direction.x);
    float alongSize=polygon.Max(p=>Vector2.Dot(p,direction))-polygon.Min(p=>Vector2.Dot(p,direction)),acrossSize=polygon.Max(p=>Vector2.Dot(p,across))-polygon.Min(p=>Vector2.Dot(p,across));
    for(int attempt=0;attempt<8;attempt++){var axis=alongSize>acrossSize?direction:across;float angle=Next(random,-.085f,.085f);var normal=new Vector2(axis.x*Mathf.Cos(angle)-axis.y*Mathf.Sin(angle),axis.x*Mathf.Sin(angle)+axis.y*Mathf.Cos(angle));float lo=polygon.Min(p=>Vector2.Dot(p,normal)),hi=polygon.Max(p=>Vector2.Dot(p,normal)),offset=Mathf.Lerp(lo,hi,Next(random,.38f,.62f));var a=Clip(polygon,normal,offset,true);var b=Clip(polygon,normal,offset,false);if(a.Count<3||b.Count<3||Area(a)<target*.3f||Area(b)<target*.3f)continue;Partition(a,target,random,plots,depth+1);Partition(b,target,random,plots,depth+1);return;}plots.Add(polygon);}
   List<List<Vector2>> RoadBlocks(Rect bounds){var blocks=new List<List<Vector2>>{new List<Vector2>{new Vector2(bounds.xMin,bounds.yMin),new Vector2(bounds.xMax,bounds.yMin),new Vector2(bounds.xMax,bounds.yMax),new Vector2(bounds.xMin,bounds.yMax)}};
    // Roads divide holdings before smaller plots are cut; fields stop along a parallel verge.
    foreach(var edge in data.roads.definition.connections){Vector2 a=data.terrain.transform.InverseTransformPoint(data.roads.transform.TransformPoint(data.roads.definition.nodes[edge.a])),b=data.terrain.transform.InverseTransformPoint(data.roads.transform.TransformPoint(data.roads.definition.nodes[edge.b]));var delta=b-a;if(delta.sqrMagnitude<.001f)continue;var direction=delta.normalized;var normal=new Vector2(-direction.y,direction.x);float offset=Vector2.Dot(a,normal),gap=data.roads.definition.roadWidth*.5f+.34f;var next=new List<List<Vector2>>();foreach(var polygon in blocks){float lo=polygon.Min(p=>Vector2.Dot(p-a,direction)),hi=polygon.Max(p=>Vector2.Dot(p-a,direction));float sideLo=polygon.Min(p=>Vector2.Dot(p,normal)),sideHi=polygon.Max(p=>Vector2.Dot(p,normal));if(hi<0||lo>delta.magnitude||sideLo>=offset+gap||sideHi<=offset-gap){next.Add(polygon);continue;}var left=Clip(polygon,normal,offset+gap,true);var right=Clip(polygon,normal,offset-gap,false);if(left.Count>=3&&Area(left)>.15f)next.Add(left);if(right.Count>=3&&Area(right)>.15f)next.Add(right);}blocks=next;}return blocks;
   }
   void InkBoundary(List<Vector2> polygon,Color ridge,System.Random random){for(int edge=0;edge<polygon.Count;edge++){var a=polygon[edge];var b=polygon[(edge+1)%polygon.Count];var d=b-a;float length=d.magnitude;if(length<.03f)continue;var normal=new Vector2(-d.y,d.x)/length;int steps=Mathf.Max(2,Mathf.CeilToInt(length/.16f));var points=new List<Vector2>();for(int j=0;j<=steps;j++)points.Add(Vector2.Lerp(a,b,j/(float)steps)+normal*(j==0||j==steps?0:Next(random,-.009f,.009f)));
     canvas.Polyline(points,.065f,ridge,.12f);canvas.Polyline(points,.033f,ridge,.21f);for(int j=1;j<points.Count;j++)if(random.NextDouble()>.08)canvas.Line(points[j-1],points[j],Next(random,.012f,.023f),ridge,Next(random,.58f,.82f));stats.inkEdges++;}}
   void Fill(List<Vector2> polygon,Color color,float alpha){var pixels=polygon.Select(canvas.Pixel).ToArray();int y0=Mathf.Max(0,Mathf.FloorToInt(pixels.Min(p=>p.y))),y1=Mathf.Min(canvas.height-1,Mathf.CeilToInt(pixels.Max(p=>p.y)));var hits=new List<float>();for(int y=y0;y<=y1;y++){hits.Clear();float line=y+.5f;for(int i=0;i<pixels.Length;i++){var a=pixels[i];var b=pixels[(i+1)%pixels.Length];if((a.y<=line&&b.y>line)||(b.y<=line&&a.y>line))hits.Add(a.x+(b.x-a.x)*(line-a.y)/(b.y-a.y));}hits.Sort();for(int i=1;i<hits.Count;i+=2)for(int x=Mathf.Max(0,Mathf.CeilToInt(hits[i-1]-.5f));x<=Mathf.Min(canvas.width-1,Mathf.FloorToInt(hits[i]-.5f));x++){var world=new Vector2(canvas.bounds.xMin+(x+.5f)/canvas.Scale,canvas.bounds.yMin+(y+.5f)/canvas.Scale);float wash=StaffMapCanvas.Noise(world.x*2.7f,world.y*2.7f,39),grain=StaffMapCanvas.Noise(world.x*41,world.y*41,91);fieldPixels[y*canvas.width+x]=true;canvas.Ink(x,y,Color.Lerp(color,Hex(0x81765D),(1-wash)*.10f),alpha*(.78f+.28f*wash+.12f*grain));}}}
   void Field(List<Vector2> polygon,MapDetailRegions.Area area,System.Random random){
    var centre=Centre(polygon);
    var rect=Rect.MinMaxRect(polygon.Min(p=>p.x),polygon.Min(p=>p.y),polygon.Max(p=>p.x),polygon.Max(p=>p.y));float fieldArea=Area(polygon);stats.smallestField=stats.smallestField==0?fieldArea:Mathf.Min(stats.smallestField,fieldArea);stats.largestField=Mathf.Max(stats.largestField,fieldArea);for(int i=0;i<polygon.Count;i++){var edge=polygon[(i+1)%polygon.Count]-polygon[i];if(Mathf.Abs(edge.x)>.03f&&Mathf.Abs(edge.y)>.03f)stats.diagonalEdges++;if(edge.sqrMagnitude>.001f){float align=Mathf.Abs(Vector2.Dot(edge.normalized,RoadDirection(centre)));if(align>Mathf.Cos(.13f)||align<Mathf.Sin(.13f))stats.roadAlignedEdges++;}}
    float cluster=StaffMapCanvas.Noise(rect.center.x*.15f,rect.center.y*.15f,area.seed);float sample=cluster*.68f+Next(random,0,1)*.32f;int color=sample<area.greenFields?Next(random,0,1)<.55f?0:1:Next(random,0,1)<.65f?3:Next(random,0,1)<.6f?2:4;stats.palette[color]++;stats.fields++;
    var tone=crops[color];tone=Color.Lerp(tone,StaffMapStyle.Paper,Next(random,.02f,.09f));Fill(polygon,tone,.62f);
    var ridge=Color.Lerp(StaffMapStyle.Ink,tone,.05f);InkBoundary(polygon,ridge,random);
    var roadDirection=RoadDirection(centre);float angle=Mathf.Atan2(roadDirection.y,roadDirection.x)+Next(random,-.06f,.06f);var normal=new Vector2(-Mathf.Sin(angle),Mathf.Cos(angle));float lo=polygon.Min(p=>Vector2.Dot(p,normal)),hi=polygon.Max(p=>Vector2.Dot(p,normal));for(float n=lo+.07f;n<hi-.03f;n+=Next(random,.11f,.16f)){var hits=new List<Vector2>();for(int i=0;i<polygon.Count;i++){var a=polygon[i];var b=polygon[(i+1)%polygon.Count];float da=Vector2.Dot(a,normal)-n,db=Vector2.Dot(b,normal)-n;if(da*db<0)hits.Add(Vector2.Lerp(a,b,da/(da-db)));}if(hits.Count>=2)canvas.Line(hits[0],hits[1],.010f,ridge,.20f);}
    if(random.NextDouble()<.35)canvas.Line(polygon[0],polygon[1],.022f,Hex(0x746C5B),.48f);
    if(random.NextDouble()<.3){var a=polygon[0];var b=polygon[1];int trees=Mathf.FloorToInt(Vector2.Distance(a,b)/.19f);for(int i=1;i<trees;i++)Tree(Vector2.Lerp(a,b,i/(float)trees),random,.05f);}
   }
   void Tree(Vector2 p,System.Random random,float size){if(!Safe(p))return;canvas.Ellipse(p,new Vector2(size,size*.8f),Hex(0x768865),.4f);canvas.Ellipse(p+new Vector2(-size*.15f,size*.16f),Vector2.one*size*.65f,Hex(0x506B55),.43f);}
   void House(Vector2 p,float angle,System.Random random){float w=Next(random,.075f,.13f),h=Next(random,.05f,.09f);var ink=Hex(0x171815);canvas.Rectangle(p,new Vector2(w,h),angle,Hex(0xB4AA8C),.24f);canvas.Rectangle(p,new Vector2(w*.55f,h*.55f),angle,ink,.73f);var direction=new Vector2(Mathf.Cos(angle),Mathf.Sin(angle));canvas.Line(p-direction*w*.45f,p+direction*w*.45f,.013f,Hex(0xE5D8BC),.75f);stats.buildings++;}
   void Village(MapDetailRegions.Area area,Vector2 centre,System.Random random){
    float radius=Mathf.Min(area.bounds.width,area.bounds.height)*.19f;radius=Mathf.Clamp(radius,.35f,1.2f);var roadDirection=RoadDirection(centre);float angle=Mathf.Atan2(roadDirection.y,roadDirection.x)+Next(random,-.12f,.12f);Vector2 direction=new Vector2(Mathf.Cos(angle),Mathf.Sin(angle)),normal=new Vector2(-direction.y,direction.x);int builtBefore=stats.buildings;var occupied=new List<Vector2>();Vector2 streetStart=centre-direction*radius,streetEnd=centre+direction*radius;
    int lots=Mathf.RoundToInt(Next(random,12,22)*area.density);for(int i=0;i<lots;i++){float along=Next(random,-radius,radius);float side=(i%2==0?1:-1)*Next(random,.14f,.36f);Vector2 p=centre+direction*along+normal*side;if(!Fits(area.bounds,p,.19f)||occupied.Any(q=>Vector2.Distance(p,q)<.30f))continue;occupied.Add(p);House(p,angle,random);if(random.NextDouble()<.6){var yard=p+normal*side*.25f;canvas.Rectangle(yard,new Vector2(.16f,.12f),angle,Hex(0xA8A27C),.14f);Tree(p+normal*side*.55f,random,.07f);}}
    if(stats.buildings==builtBefore)return;stats.villages++;stats.villageCentres.Add(centre);canvas.Line(streetStart,streetEnd,.047f,Hex(0xDED3B6),.80f);canvas.Line(streetStart,streetEnd,.012f,Hex(0x24241D),.38f);
    float best=float.PositiveInfinity;Vector2 junction=centre;foreach(var edge in data.roads.definition.connections){Vector2 a=data.terrain.transform.InverseTransformPoint(data.roads.transform.TransformPoint(data.roads.definition.nodes[edge.a])),b=data.terrain.transform.InverseTransformPoint(data.roads.transform.TransformPoint(data.roads.definition.nodes[edge.b]));var d=b-a;var p=a+d*Mathf.Clamp01(Vector2.Dot(centre-a,d)/Mathf.Max(.000001f,d.sqrMagnitude));if(Vector2.Distance(centre,p)<best){best=Vector2.Distance(centre,p);junction=p;}}
    if(best<4&&area.bounds.Contains(junction)){bool clear=true;for(int i=1;i<16;i++)if(!Safe(Vector2.Lerp(centre,junction,i/16f))){clear=false;break;}if(clear){var bend=Vector2.Lerp(streetEnd,junction,.5f)+normal*.1f;canvas.Polyline(new[]{streetEnd,bend,junction},.026f,Hex(0x24241D),.43f);}}
   }
   public void Draw(MapDetailRegions.Area area){
    if(area==null||area.bounds.width<.3f||area.bounds.height<.3f)return;var random=new System.Random(area.seed);var villages=new List<Vector2>();if(area.kind!=MapDetailRegions.DetailKind.Farmland){int count=area.kind==MapDetailRegions.DetailKind.Village?1:Mathf.Clamp(Mathf.RoundToInt(area.bounds.width*area.bounds.height*area.density/65),1,5);for(int n=0;n<count;n++)for(int attempt=0;attempt<60;attempt++){Vector2 centre=new Vector2(Next(random,area.bounds.xMin+area.bounds.width*.2f,area.bounds.xMax-area.bounds.width*.2f),Next(random,area.bounds.yMin+area.bounds.height*.2f,area.bounds.yMax-area.bounds.height*.2f));if(!Fits(area.bounds,centre,.4f)||villages.Any(p=>Vector2.Distance(p,centre)<2))continue;villages.Add(centre);break;}}
    float step=Mathf.Clamp(area.plotScale,.2f,2)*1.35f/Mathf.Sqrt(Mathf.Clamp(area.density,.2f,2));var b=area.bounds;var plots=new List<List<Vector2>>();foreach(var block in RoadBlocks(b))Partition(block,step*step,random,plots);if(data.generateFarmland)foreach(var raw in plots){var polygon=Inset(raw,.075f);if(!ClearPlot(polygon,villages)){stats.rejectedPlots++;continue;}var centre=Centre(polygon);if(random.NextDouble()<(area.kind==MapDetailRegions.DetailKind.Village?.45:.09))continue;if(villages.Any(p=>Vector2.Distance(p,centre)<1.35f))continue;if(!Fits(area.bounds,centre,.08f))continue;occupiedFields.Add(polygon);if(fieldPixels==null)fieldPixels=new bool[canvas.pixels.Length];Field(polygon,area,random);}
    foreach(var village in villages)Village(area,village,random);
   }
   public Texture2D Finish(){int maskWidth=800,maskHeight=Mathf.RoundToInt(maskWidth*canvas.bounds.height/canvas.bounds.width);var allowed=new bool[maskWidth*maskHeight];for(int y=0;y<maskHeight;y++)for(int x=0;x<maskWidth;x++){var p=new Vector2(canvas.bounds.xMin+(x+.5f)*canvas.bounds.width/maskWidth,canvas.bounds.yMin+(y+.5f)*canvas.bounds.height/maskHeight);allowed[y*maskWidth+x]=data.areas.Any(a=>a!=null&&a.bounds.Contains(p))&&Safe(p);}
    for(int y=0;y<canvas.height;y++)for(int x=0;x<canvas.width;x++){int i=y*canvas.width+x;var c=canvas.pixels[i];bool inside=false;if(c.a>0){var p=new Vector2(canvas.bounds.xMin+(x+.5f)/canvas.Scale,canvas.bounds.yMin+(y+.5f)*canvas.bounds.height/canvas.height);foreach(var area in data.areas)if(area!=null&&area.bounds.Contains(p)){inside=true;break;}}if(!inside||!allowed[(y*maskHeight/canvas.height)*maskWidth+x*maskWidth/canvas.width]){if(fieldPixels!=null&&fieldPixels[i])stats.clippedFieldPixels++;c=Color.clear;}else if(c.a>.00001f){c.r/=c.a;c.g/=c.a;c.b/=c.a;}canvas.pixels[i]=c;}
    var texture=new Texture2D(canvas.width,canvas.height,TextureFormat.RGBA32,false){filterMode=FilterMode.Bilinear,wrapMode=TextureWrapMode.Clamp};texture.SetPixels(canvas.pixels);texture.Apply();return texture;
   }
  }
  public static Texture2D Generate(MapDetailRegions data,out Statistics stats,int resolution=0){data.Resolve();var painter=new Painter(data,resolution>0?resolution:data.resolution);foreach(var area in data.areas)painter.Draw(area);var result=painter.Finish();stats=painter.stats;return result;}
  public static void Bake(MapDetailRegions data){
   if(EditorApplication.isPlaying)throw new InvalidOperationException("请停止运行后制作地图");Statistics stats;var texture=Generate(data,out stats);const string folder="Assets/Game/MapDetailCache";Directory.CreateDirectory(folder);string path=folder+"/"+data.gameObject.scene.name+".png";File.WriteAllBytes(path,texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spritePixelsPerUnit=100;importer.mipmapEnabled=false;importer.alphaIsTransparency=true;importer.maxTextureSize=4096;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.wrapMode=TextureWrapMode.Clamp;importer.SaveAndReimport();
   if(data.bakedView==null){var obj=new GameObject("区域生成细节 · 村落与田块");Undo.RegisterCreatedObjectUndo(obj,"生成地图细节层");obj.transform.SetParent(data.terrain.transform,false);data.bakedView=obj.AddComponent<SpriteRenderer>();}var view=data.bakedView;Undo.RecordObject(view,"更新地图细节");view.sprite=AssetDatabase.LoadAssetAtPath<Sprite>(path);view.sortingOrder=4;var bounds=data.terrain.definition.bounds;view.transform.localPosition=bounds.center;view.transform.localScale=new Vector3(bounds.width/view.sprite.bounds.size.x,bounds.height/view.sprite.bounds.size.y,1);
   var legacy=GameObject.Find("麦田与草地 · 纯贴图装饰");if(legacy!=null){var renderer=legacy.GetComponent<SpriteRenderer>();if(renderer!=null){Undo.RecordObject(renderer,"替换旧大片麦田");renderer.enabled=false;}}
   data.generatedFields=stats.fields;data.generatedBuildings=stats.buildings;data.generatedVillages=stats.villages;EditorUtility.SetDirty(data);EditorSceneManager.MarkSceneDirty(data.gameObject.scene);
  }
 }
}


